#[cfg(windows)]
const CREATE_NO_WINDOW: u32 = 0x0800_0000;

#[derive(Debug)]
pub struct Output {
    /// タイムアウトで打ち切ったときは None
    pub code: Option<i32>,
    pub stdout: String,
    pub stderr: String,
    pub timed_out: bool,
}

impl Output {
    pub fn success(&self) -> bool {
        self.code == Some(0)
    }
}

/// 子プロセス用の `Command` を作る。Windows では窓が一瞬出ないようフラグを付ける
pub fn command(program: impl AsRef<std::ffi::OsStr>) -> Command {
    #[allow(unused_mut)]
    let mut command = Command::new(program);
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
/// 実行して出力を集める。時間切れなら子孫ごと kill し、そこまでの出力を返す。
/// 子が正常に終わった場合も、子が残していった子孫（バックグラウンドの孫など）は止める
pub fn run(mut command: Command, stdin: Option<&str>, timeout: Duration) -> Result<Output> {
    command
        .stdin(if stdin.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut tree = Tree::prepare(&mut command);
    let mut child = command
        .spawn()
        .with_context(|| format!("failed to start {:?}", command.get_program()))?;
    tree.attach(&mut child);
    }
    let path = std::env::var_os("PATH")?;
    std::env::split_paths(&path).find_map(|dir| candidates(&dir))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// テスト用に、シェル経由でスクリプトを走らせる Command を作る
    fn shell(script: &str) -> Command {
        if cfg!(windows) {
            let mut cmd = command("powershell");
            cmd.args(["-NoProfile", "-Command", script]);
            cmd
        } else {
            let mut cmd = command("sh");
            cmd.args(["-c", script]);
            cmd
        }
    }

    #[test]
    fn captures_stdout_and_exit_code() {
        let script = "echo hello; exit 3";
        let output = run(shell(script), None, Duration::from_secs(30)).unwrap();

/// フラグ判定に使う、解決済みの場所。環境変数はここへ渡す前に呼び出し側が読む
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Roots {
    os: Os,
    /// 正規化済み。末尾の区切りは無い
    user_writable: Vec<String>,
    /// 正規化済み（Windows の `%SystemRoot%`）
    system_root: String,
}

impl Roots {
    /// 渡す値は正規化前でよい。空や根（`/`）は、全部が書き込み可能になってしまうので捨てる
    pub fn new(os: Os, user_writable: &[&str], system_root: Option<&str>) -> Roots {
        let trim = |p: &str| {
            let (p, _) = normalize_basic(os, p);
            p.trim_end_matches(os.separator()).to_string()
        };
        Roots {
            os,
            user_writable: user_writable
                .iter()
                .map(|p| trim(p))
                .filter(|p| !p.is_empty())
                .collect(),
            system_root: trim(system_root.unwrap_or(r"C:\Windows")),
        }
    }

    /// 実行中の環境から組み立てる。環境変数を読むのはここだけ
    pub fn from_env() -> Roots {
        let os = Os::current();
        let var = |name: &str| std::env::var(name).unwrap_or_default();
        match os {
            Os::Windows => {
                let (profile, temp, tmp, root) = (
                    var("USERPROFILE"),
                    var("TEMP"),
                    var("TMP"),
                    var("SystemRoot"),
                );
                let root = (!root.is_empty()).then_some(root.as_str());
                Roots::new(os, &[&profile, &temp, &tmp, r"C:\Users\Public"], root)
            }
            Os::Linux => {
                let home = var("HOME");
                Roots::new(os, &[&home, "/tmp", "/var/tmp", "/dev/shm"], None)
            }
        }
    }
}

/// `path` が `dir` と同じか、その配下にあるか。どちらも正規化済み
fn is_under(sep: char, path: &str, dir: &str) -> bool {
    path.strip_prefix(dir)
        .is_some_and(|rest| rest.is_empty() || rest.starts_with(sep))
}

