        let mut buffer: Vec<u64> = Vec::new();
        for _ in 0..4 {
            let pointer = (!buffer.is_empty()).then(|| buffer.as_mut_ptr().cast::<c_void>());
            let status = fetch(pointer, &mut size);
            if status == NO_ERROR.0 {
                return Ok(buffer);
            }
            if status != ERROR_INSUFFICIENT_BUFFER.0 {
                bail!("GetExtended*Table failed: {status}");
            }
            // 件数の増加に備えて余裕を持つ
            buffer = vec![0; (size as usize + 1024).div_ceil(8)];
            size = (buffer.len() * 8) as u32;
        }
        bail!("the table kept growing")
    }

    /// 成功した表の件数と、行の先頭を返す
    macro_rules! rows {
        ($buffer:expr, $table:ty, $row:ty) => {{
